def main():
 audit={r['sheet']:r for b in json.loads((ROOT/'evidence/sheet_report_number_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};dates={r['sheet']:r for b in json.loads((ROOT/'evidence/status_report_date_audit.json').read_text())['workbooks'] if b['file']==SRC for r in b['rows']};wb=load_workbook(ROOT/SRC,read_only=True,data_only=True);items=[]
 for prefix,cells,anchor,en,fa in EVENTS:
  sheet=f'{prefix}-1 Remark';values={c:wb[sheet][c].value for c in cells};assert all(isinstance(v,str) and v.strip() for v in values.values()),(sheet,values);assert anchor.lower() in ' '.join(values.values()).lower(),(sheet,anchor);num=audit[sheet]['header_report_number'];assert isinstance(num,int)
  items.append({'sheet':sheet,'worksheet_prefix':prefix,'header_report_number':num,'header_date_unverified':dates[sheet]['report_date_iso_from_header'],'cells':values,'anchor':anchor,'english':en,'persian':fa})
 wb.close();items.sort(key=lambda x:(x['header_report_number'],x['worksheet_prefix']));pg=' '.join(PdfReader(ROOT/PROGRAM).pages[6].extract_text().split());assert '39 (Main Plan) + 9 (Contingency Plan)' in pg
 cw=load_workbook(ROOT/CBS,read_only=True,data_only=True);fw=load_workbook(ROOT/CBS,read_only=True,data_only=False);refs={'Cost Breakdown-10 w. Extra Wor':['A4','D5','E5','F5','G5','H5','F191'],'Cost Breakdown-10':['A4','D5','E5','F5','F190']};fin={s:{c:{'cached':cw[s][c].value,'formula_or_literal':fw[s][c].value} for c in cells} for s,cells in refs.items()};cw.close();fw.close()
 data={'well':'10','source':SRC,'method':'Selected observations sorted by numeric source header; ties sorted by worksheet prefix for display only, not signed chronology.','events':items,'programme':{'file':PROGRAM,'physical_page':7,'text_excerpt':pg},'cbs':{'file':CBS,'cells':fin,'caveat':'Cached workbook values and row/sheet labels only; formulas not recalculated, actual cost or independent extra-work authorization not established. Do not add totals without scope reconciliation.'},'limitations':'Selected records do not establish all events, accepted tests, current barriers, actual costs or contractual liability.'};(ROOT/'evidence/10_campaign_review.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 for lang in ('EN','FA'):
  fa=lang=='FA';path=ROOT/f'10_Drilling_Engineering_Report_{lang}.docx';d=Document(path);title='بازسازی منتخب عملیات رفع تعلیق و تکمیل چاه ۱۰' if fa else 'Selected AZNS-10 de-suspension and completion campaign reconstruction'
  if any(p.text==title for p in d.paragraphs):continue
  anchor=next(p for p in d.paragraphs if p.text in ('Performance and Parameter Analysis','تحلیل عملکرد و پارامترهای عملیاتی'));h=d.add_heading(title,level=2);h.alignment=1;anchor._p.addprevious(h._p)
  p=d.add_paragraph(f'این {len(items)} مدخل منتخب بر اساس شماره سرصفحه مرتب و در صورت تساوی صرفاً برای نمایش بر اساس پیشوند شیت مرتب شده‌اند. این ترتیب و تاریخ‌ها گاه‌شمار تأییدشده نیستند. شیت‌های ۲۷ و ۲۸ هر دو سرصفحه ۲۷ دارند؛ سوابق امضاشده برای رفع ابهام لازم است.' if fa else f'These {len(items)} selected entries are sorted by source header number, with worksheet prefix used only to display ties; neither this order nor header dates are verified chronology. Worksheets 27 and 28 both carry header 27; signed records are needed to resolve the ambiguity.');style(p,fa);anchor._p.addprevious(p._p)
