   lead=f"شیت {e['worksheet_prefix']}، شماره سرصفحه {e['header_report_number']} ـ " if fa else f"Worksheet {e['worksheet_prefix']}, header report {e['header_report_number']} — ";cite=f"{SRC}, {e['sheet']}!"+', '.join(e['cells']);p=d.add_paragraph(lead+e['persian' if fa else 'english']+f' [{cite}]');style(p,fa);anchor._p.addprevious(p._p)
